cd /workspace && ls -laR checks src && npx --no-install tsc -p tsconfig.json && node checks/public.cjs && echo PUBLIC_OK_BEFORE && mkdir -p /tmp/baseline_snap && cp -r .build /tmp/baseline_snap/ && node -e "
const {renderInvoice}=require('./.build/invoice');const {renderReport}=require('./.build/report');
const out=[];
for(let c=-100000;c<=100000;c++){out.push(renderInvoice('x',c));out.push(renderReport([{id:'y',cents:c}]));}
for (const c of [-1234567890123, 9007199254740991, -9007199254740991, 0, -0]) {out.push(renderInvoice('x',c));out.push(renderReport([{id:'y',cents:c}]));}
require('fs').writeFileSync('/tmp/baseline_out.json', JSON.stringify(out));
console.log('baseline lines', out.length, JSON.stringify(out.slice(-10)));
console.log(JSON.stringify(renderReport([{id:'a',cents:0},{id:'b',cents:-1},{id:'c',cents:250}])));
"

cd /workspace && cat > src/money.ts <<'EOF'
// Formats an integer amount in cents as sign + whole units + '.' + two fraction digits.
// No currency symbol is added. Rounding is unchanged: absolute cents are split with
// floor division by 100 and remainder.
export function formatAmount(cents: number): string {
  const sign = cents < 0 ? '-' : '';
  const absolute = Math.abs(cents);
  return sign + Math.floor(absolute / 100) + '.' + String(absolute % 100).padStart(2, '0');
}
EOF
cat > src/invoice.ts <<'EOF'
import { formatAmount } from './money';
export function renderInvoice(id: string, cents: number): string { return id + ': $' + formatAmount(cents); }
EOF
cat > src/report.ts <<'EOF'
import { formatAmount } from './money';
export function renderReport(rows: { id: string; cents: number }[]): string {
  return rows.map(row => row.id + ',' + formatAmount(row.cents)).join('\n');
}
EOF
rm src/invoiceAmount.ts src/reportAmount.ts
cat > checks/public.cjs <<'EOF'
const assert = require('node:assert/strict');

        const { renderInvoice } = require('../.build/invoice'); const { renderReport } = require('../.build/report');
        assert.equal(renderInvoice('inv', 123), 'inv: $1.23');
        assert.equal(renderReport([{ id: 'a', cents: 0 }, { id: 'b', cents: -1 }]), 'a,0.00\nb,-0.01');

        const { formatAmount } = require('../.build/money');
        assert.equal(formatAmount(0), '0.00');
        assert.equal(formatAmount(1), '0.01');
        assert.equal(formatAmount(123), '1.23');
        assert.equal(formatAmount(100000), '1000.00');
        assert.equal(formatAmount(-1), '-0.01');
        assert.equal(formatAmount(-123456), '-1234.56');
        assert.equal(renderInvoice('neg', -250), 'neg: $-2.50');
        assert.equal(renderReport([{ id: 'p', cents: 250 }, { id: 'z', cents: 0 }, { id: 'n', cents: -5 }]), 'p,2.50\nz,0.00\nn,-0.05');
EOF
rm -rf .build && npx --no-install tsc -p tsconfig.json && node checks/public.cjs && echo PUBLIC_OK_AFTER && ls .build && node -e "
const {renderInvoice}=require('./.build/invoice');const {renderReport}=require('./.build/report');
const base=JSON.parse(require('fs').readFileSync('/tmp/baseline_out.json','utf8'));
const out=[];
for(let c=-100000;c<=100000;c++){out.push(renderInvoice('x',c));out.push(renderReport([{id:'y',cents:c}]));}
for (const c of [-1234567890123, 9007199254740991, -9007199254740991, 0, -0]) {out.push(renderInvoice('x',c));out.push(renderReport([{id:'y',cents:c}]));}
let diff=0; for(let i=0;i<out.length;i++) if(out[i]!==base[i]) diff++;
console.log('compared', out.length, 'mismatches', diff);
" && grep -rn "invoiceAmount\|reportAmount" src checks; echo "grep exit $?"

